public class Main {
    static class SSP {
        int n, source, sink;
        List<List<Integer>> adj;
        static class edge {
            int u, flow, cap, cost, origcost;
        }
        List<edge> edges;
        SSP(int n, int source, int sink) {
            this.n = n;
            this.source = source;
            this.sink = sink;
            this.adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                this.adj.add(new ArrayList<>());
            }
            this.edges = new ArrayList<>();
