        int add_edge(int a, int b, int cap, int cost) {
            int result = edges.size();
            adj.get(a).add(edges.size());
            edges.add(new edge(b, 0, cap, cost, cost));
            adj.get(b).add(edges.size());
            edges.add(new edge(a, 0, 0, -cost, -cost));
            return result;
        }
        Pair djk() {
            class state_t {
                int dist, prev, maxf;
            }
            PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.first));
            state_t[] states = new state_t[n];
            for (int i = 0; i < n; i++) {
                states[i] = new state_t();
                states[i].dist = Integer.MAX_VALUE / 2;
                states[i].prev = -1;
                states[i].maxf = 0;
